      tables: [['Organisers', ['Function', 'Connectors'], [['Opening', 'en primer lugar, para empezar, ante todo, de entrada'], ['Continuing', 'en segundo lugar, a continuación, por otra parte, asimismo'], ['Closing a list', 'por último, finalmente, para terminar'], ['Exemplifying', 'por ejemplo, así, tal es el caso de, sin ir más lejos'], ['Reformulating', 'es decir, o sea, dicho de otro modo, mejor dicho'], ['Emphasising', 'de hecho, en efecto, sobre todo, cabe destacar'], ['Digressing', 'por cierto, a propósito, dicho sea de paso'], ['Returning', 'volviendo a lo anterior, como decía'], ['Concluding', 'en conclusión, en definitiva, en suma, en resumen, para concluir']], [1]]],
