      quiz: [mc('«ante todo» =', ['above all / first of all', 'before everything ended'], 0), mc('«volviendo a lo anterior» is used to…', ['return to a point', 'conclude'], 0), mc('«en efecto» =', ['indeed', 'in effect'], 0), mc('«a continuación» =', ['next', 'to continue later'], 0), mc('Best essay ending:', ['En definitiva, …', 'Por cierto, …'], 0)]
