      examples: [['El café lo pago yo.', 'I’ll pay for the coffee.'], ['Eso sí que no me lo esperaba.', 'Now that I really didn’t expect.'], ['Ven aquí mismo.', 'Come right here.'], ['Lo terminé ayer mismo.', 'I finished it just yesterday.'], ['Quiero un té bien cargado.', 'I want a really strong tea.'], ['Es un autor archiconocido.', 'He’s an extremely well-known author.']],
      mistakes: [['El libro compré ayer.', 'El libro lo compré ayer.'], ['Sí es verdad (emphatic, fine) — but ❌ Sí que es (in negative contrast misuse)', 'Eso sí que es verdad.'], ['muy superbién', 'superbién']],
      practice: [bd(['las', 'entradas', 'las', 'tengo', 'yo'], 'las entradas las tengo yo', 'I’m the one with the tickets.'), mc('Topic first: «La paella ___ hace mi abuela.»', ['la', '—'], 0), fl('Eso ___ que es bonito. (really)', ['sí', 'si']), fl('Lo quiero para hoy ___. (this very day)', ['mismo']), mc('a really cold beer:', ['una cerveza bien fría', 'una cerveza fría bien'], 0), tr('I paid for the dinner. (topic first)', ['la cena la pagué yo', 'la cena la pagué'])],
      quiz: [mc('«Lo hizo Ana» focuses on…', ['Ana', 'the action'], 0), mc('«ahora mismo» =', ['right now', 'now the same'], 0), mc('Topic-first requires…', ['a resumptive pronoun', 'nothing'], 0), mc('«bien» before an adjective =', ['well', 'very'], 1), mc('«archiconocido» =', ['very well known', 'unknown'], 0)]
