  /* ================= UNIT 6 · ORACIONES CONDICIONALES ================= */
  G.unit('advanced', 'au6', 'Oraciones condicionales', 'Real, hypothetical, impossible, mixed and advanced conditions', [
    L('a_si_real', 'Real conditional sentences', 'C1', 'si + indicative: rules, habits, warnings', {
      explain: P('<b>Real (probable) conditions</b>: si + present / past indicative. The result can be present, future, imperative, or even past for past habits.'),
      tables: [['Real conditions', ['si-clause', 'Result', 'Example'], [['si + present', 'present (rule)', 'Si calientas el agua a 100°, hierve.'], ['si + present', 'future', 'Si llueve, nos quedaremos.'], ['si + present', 'imperative', 'Si ves a Lola, salúdala.'], ['si + perfecto', 'present / imperative', 'Si has terminado, puedes irte.'], ['si + imperfecto', 'imperfecto (past habit)', 'Si llovía, nos quedábamos en casa.'], ['si + indefinido', 'present/past (logical)', 'Si lo dijo, será verdad.']], [2]]],
      rules: [['Never future or present subjunctive after si', '❌ si lloverá / si llueva'], ['si = whenever (habit)', 'Si tengo tiempo, leo.']],
      examples: [['Si mezclas azul y amarillo, sale verde.', 'If you mix blue and yellow, you get green.'], ['Si me necesitas, llámame.', 'If you need me, call me.'], ['Si has acabado, revisa el informe.', 'If you’ve finished, check the report.'], ['De pequeña, si me portaba bien, me compraban un helado.', 'As a child, if I behaved, they bought me an ice cream.'], ['Si te lo prometió, lo hará.', 'If she promised you, she’ll do it.'], ['Si no estudias, no apruebas.', 'If you don’t study, you don’t pass.']],
      mistakes: [['Si lloverá, no iremos.', 'Si llueve, no iremos.'], ['Si tengas tiempo…', 'Si tienes tiempo…']],
      practice: [fl('Si ___ (tener, tú) hambre, come algo.', ['tienes']), fl('Si ___ (llover) mañana, no iremos.', ['llueve']), fl('De niños, si ___ (hacer) sol, íbamos a la playa.', ['hacía', 'hacia']), mc('If you have finished:', ['Si terminarás…', 'Si has terminado…'], 1), mc('Correct:', ['Si vendrá, avísame.', 'Si viene, avísame.'], 1), tr('If you see Marc, say hello to him.', ['si ves a marc, salúdalo', 'si ves a marc, salúdale', 'si ves a marc saludalo'])],
      quiz: [mc('si + future is…', ['correct', 'wrong'], 1), mc('Past habit: si + …', ['imperfecto', 'pluscuamperfecto subj.'], 0), mc('General rule: si + present → …', ['present', 'conditional'], 0), mc('«Si lo dijo, será verdad» — será =', ['probability', 'future fact'], 0), mc('Imperative result:', ['Si puedes, ven.', 'Si puedes, vendrías.'], 0)]
    }),
    L('a_si_hypo', 'Hypothetical conditional sentences', 'C1', 'si + imperfect subjunctive → conditional', {
      explain: P('<b>Hypothetical conditions</b> (unlikely or contrary to present reality): <b>si + imperfect subjunctive → conditional</b>.'),
      tables: [['Hypothetical', ['si-clause', 'Result', 'Example'], [['si + imp. subj.', 'condicional simple', 'Si tuviera tiempo, aprendería árabe.'], ['si + imp. subj.', 'condicional (future reference)', 'Si mañana lloviera, no saldríamos.'], ['si + imp. subj. (-se)', 'condicional', 'Si fuese posible, lo haría.']], [2]]],
      rules: [['-ra / -se both correct', 'si tuviera = si tuviese'], ['Colloquial: imperfect subj. also in result (avoid in writing)', '❌ Si tuviera dinero, me comprara… (dialectal)'], ['Present unreal vs future unlikely', 'Si fuera rica… (I’m not) / Si ganara la lotería… (unlikely)']],
      examples: [['Si viviera en Valencia, iría a las Fallas cada año.', 'If I lived in Valencia, I’d go to the Fallas every year.'], ['Si me tocara la lotería, dejaría de trabajar.', 'If I won the lottery, I’d stop working.'], ['Si fuera tú, no lo firmaría.', 'If I were you, I wouldn’t sign it.'], ['¿Qué harías si no tuvieras miedo?', 'What would you do if you weren’t afraid?'], ['Si hablaras más despacio, te entendería.', 'If you spoke more slowly, I’d understand you.'], ['Si fuese más barato, lo compraríamos.', 'If it were cheaper, we’d buy it.']],
      mistakes: [['Si tendría tiempo…', 'Si tuviera tiempo…'], ['Si sería tú…', 'Si fuera tú…'], ['Si tuviera dinero, compraré…', 'Si tuviera dinero, compraría…']],
      practice: [fl('Si ___ (saber, yo) la respuesta, te la diría.', ['supiera', 'supiese']), fl('Si tuviera un año libre, ___ (viajar) por Asia.', ['viajaría', 'viajaria']), fl('¿Qué ___ (hacer, tú) si fueras alcaldesa?', ['harías', 'harias']), mc('Si ___ más tiempo, leería más.', ['tendría', 'tuviera'], 1), mc('If I were you:', ['Si fuera tú', 'Si sería tú'], 0), tr('If I spoke Spanish perfectly, I would work in Madrid.', ['si hablara español perfectamente, trabajaría en madrid', 'si hablara español perfectamente trabajaría en madrid', 'si hablase español perfectamente, trabajaría en madrid'])],
      quiz: [mc('Hypothetical: si + …', ['imperfect subjunctive', 'present subjunctive'], 0), mc('Result clause:', ['conditional', 'future'], 0), mc('«si tuviese» =', ['si tuviera', 'si tenga'], 0), mc('Si ___ (poder), te ayudaría.', ['pudiera', 'podría'], 0), mc('Unlikely future also uses…', ['si + imp. subj.', 'si + future'], 0)]
    }),
    L('a_si_past', 'Impossible and past hypothetical conditions', 'C1', 'si + pluperfect subjunctive → conditional perfect', {
      explain: P('<b>Impossible conditions</b> refer to the past that cannot be changed: <b>si + hubiera + participle → habría + participle</b> (or hubiera + participle).'),
      tables: [['Past unreal', ['si-clause', 'Result', 'Example'], [['si + hubiera + part.', 'habría + part.', 'Si hubiera estudiado, habría aprobado.'], ['si + hubiera + part.', 'hubiera + part. (also correct)', 'Si hubiera estudiado, hubiera aprobado.'], ['de + haber + part.', 'habría + part.', 'De haberlo sabido, no habría venido.']], [2]]],
      rules: [['Never «si habría»', '❌ Si habría sabido'], ['de + infinitive compuesto = si + pluperfect', 'De haber salido antes… = Si hubiéramos salido antes…'], ['Regret: ojalá / si al menos + hubiera', '¡Si al menos me hubieras avisado!']],
      examples: [['Si me hubieras llamado, te habría recogido.', 'If you had called me, I would have picked you up.'], ['Si no hubiera llovido, habríamos ido a la playa.', 'If it hadn’t rained, we would have gone to the beach.'], ['De haberlo sabido, te lo habría dicho.', 'Had I known, I would have told you.'], ['Si hubiéramos salido antes, no habríamos perdido el tren.', 'If we had left earlier, we wouldn’t have missed the train.'], ['¡Si al menos me hubieras escuchado!', 'If only you had listened to me!'], ['Si lo hubiese visto, me habría acordado.', 'If I had seen it, I would have remembered.']],
      mistakes: [['Si habría sabido…', 'Si hubiera sabido…'], ['De haber sabido lo, …', 'De haberlo sabido, …'], ['Si hubiera estudiado, aprobaría (meaning past)', 'Si hubiera estudiado, habría aprobado.']],
      practice: [fl('Si ___ ___ (tú, venir), lo habrías visto.', ['hubieras venido', 'hubieses venido']), fl('Si hubiera sabido, no ___ ___ (yo, ir).', ['habría ido', 'habria ido', 'hubiera ido']), fl('De ___ ___ (saber)lo, te habría avisado.', ['haberlo sabido', 'haber sabido']), mc('If only you had told me!', ['¡Si al menos me lo hubieras dicho!', '¡Si al menos me lo habrías dicho!'], 0), mc('Correct:', ['Si habría llegado antes…', 'Si hubiera llegado antes…'], 1), tr('If I had known, I would have come.', ['si hubiera sabido, habría venido', 'si lo hubiera sabido, habría venido', 'de haberlo sabido, habría venido', 'si hubiera sabido, hubiera venido'])],
      quiz: [mc('Past unreal result:', ['habría + participle', 'habrá + participle'], 0), mc('«De haberlo sabido» =', ['Had I known', 'Of knowing it'], 0), mc('Can the result use «hubiera + part.»?', ['Yes', 'No'], 0), mc('Never after si:', ['hubiera', 'habría'], 1), mc('«Si al menos…» expresses…', ['regret', 'condition only'], 0)]
    }),
    L('a_si_mixed', 'Mixed conditional sentences', 'C1–C2', 'Past condition → present result, and vice versa', {
      explain: P('<b>Mixed conditionals</b> combine times: a <b>past</b> unreal condition with a <b>present</b> result, or a <b>present/permanent</b> unreal condition with a <b>past</b> result.'),
      tables: [['Mixed types', ['Condition', 'Result', 'Example'], [['past unreal (hubiera + part.)', 'present (condicional simple)', 'Si hubiera estudiado Medicina, ahora sería médica.'], ['present / permanent unreal (imp. subj.)', 'past (habría + part.)', 'Si fuera más valiente, habría aceptado el trabajo.'], ['real past (indicative)', 'present / imperative', 'Si ayer no dormiste, échate una siesta.']], [2]]],
      rules: [['Choose each tense by its own time', 'condition time ≠ result time'], ['ahora / hoy en día signal present result', 'Si me hubieras hecho caso, ahora no estarías así.']],
      examples: [['Si hubiera aceptado ese trabajo, ahora viviría en Madrid.', 'If I had accepted that job, I’d live in Madrid now.'], ['Si no fuera tan tímida, habría hablado con él.', 'If I weren’t so shy, I would have talked to him.'], ['Si me hubieras hecho caso, ahora no tendrías este problema.', 'If you’d listened to me, you wouldn’t have this problem now.'], ['Si supiera nadar, me habría bañado.', 'If I could swim, I would have gone in.'], ['Si no hubieras nacido en Canadá, ¿hablarías inglés?', 'If you hadn’t been born in Canada, would you speak English?'], ['Si anoche no cenaste, desayuna bien.', 'If you didn’t have dinner last night, have a good breakfast.']],
      mistakes: [['Si hubiera estudiado, ahora habría sido médica.', '…ahora sería médica.'], ['Si fuera valiente, aceptaría (meaning past)', '…habría aceptado.']],
      practice: [mc('Past condition, present result: «Si hubiera ahorrado, ahora ___ un piso.»', ['tendría', 'habría tenido'], 0), mc('Permanent condition, past result: «Si fuera más paciente, no ___ .»', ['me enfadaría', 'me habría enfadado'], 1), fl('Si me hubieras escuchado, ahora no ___ (estar, tú) así.', ['estarías', 'estarias']), fl('Si ___ (hablar, yo) alemán, habría conseguido el puesto.', ['hablara', 'hablase']), mc('Signal of present result:', ['ahora', 'ayer'], 0), tr('If I had studied Medicine, I would be a doctor now.', ['si hubiera estudiado medicina, ahora sería médica', 'si hubiera estudiado medicina, ahora sería médico', 'si hubiera estudiado medicina ahora sería médica'])],
      quiz: [mc('Mixed conditionals combine…', ['different times', 'two languages'], 0), mc('Si hubiera nacido en España, ahora ___ con ceceo.', ['hablaría', 'habría hablado'], 0), mc('Si fuera rica, ___ esa casa el año pasado.', ['compraría', 'habría comprado'], 1), mc('Each tense is chosen by…', ['its own time reference', 'the main verb only'], 0), mc('Real past condition + imperative:', ['Si no comiste, come algo.', 'Si no comieras, come algo.'], 0)]
    }),
    L('a_si_adv', 'Advanced uses of si and conditional connectors', 'C2', 'de + inf., con que, siempre que, como, a no ser que…', {
      explain: P('Spanish has many alternatives to <b>si</b>, each with its own nuance and mood.'),
      tables: [['Conditional connectors', ['Connector', 'Mood', 'Nuance / Example'], [['de + infinitive', '—', 'formal/literary: De ser así, … (If so…)'], ['con + infinitive', '—', 'minimal condition: Con llamar, basta.'], ['con que + subjunctive', 'subj.', 'it’s enough that: Con que me avises, vale.'], ['siempre que / siempre y cuando', 'subj.', 'provided that: siempre que vuelvas pronto'], ['con tal de que', 'subj.', 'as long as: con tal de que me ayudes'], ['a no ser que / a menos que', 'subj.', 'unless'], ['salvo que / excepto que', 'subj.', 'except if'], ['en caso de que', 'subj.', 'in case (formal)'], ['como + subjunctive', 'subj.', 'warning/threat: Como no vengas, me enfado.'], ['gerund', '—', 'Saliendo ahora, llegamos. (If we leave now…)']], [1, 2]]],
      rules: [['si + present in rhetorical protest', '¡Si ya te lo dije!'], ['por si (acaso) + indicative', 'Llévate paraguas por si llueve.']],
      examples: [['De ser cierto, sería un escándalo.', 'If true, it would be a scandal.'], ['Con que me lo digas un día antes, es suficiente.', 'As long as you tell me a day before, that’s enough.'], ['Te lo presto siempre y cuando me lo devuelvas.', 'I’ll lend it to you provided you give it back.'], ['Iremos a la playa, a no ser que llueva.', 'We’ll go to the beach unless it rains.'], ['Como vuelvas a llegar tarde, te despido.', 'If you’re late again, I’ll fire you.'], ['Trabajando así, acabarás agotada.', 'If you keep working like this, you’ll end up exhausted.']],
      mistakes: [['A menos que llueve', 'A menos que llueva'], ['Siempre que vuelves (condition)', 'Siempre que vuelvas'], ['Con que me llamas', 'Con que me llames']],
      practice: [fl('Iré, a no ser que ___ (llover).', ['llueva']), fl('Te ayudo con tal de que me ___ (invitar, tú) a cenar.', ['invites']), fl('Como no ___ (estudiar, tú), suspenderás.', ['estudies']), mc('Formal «if so»:', ['De ser así', 'Si así'], 0), mc('in case (formal):', ['en caso de que', 'en caso que de'], 0), tr('Unless you call me, I won’t go.', ['a no ser que me llames, no iré', 'a menos que me llames, no iré', 'a no ser que me llames no voy'])],
      quiz: [mc('«siempre que» (condition) takes…', ['indicative', 'subjunctive'], 1), mc('«Como no vengas…» expresses…', ['a warning', 'a comparison'], 0), mc('«Con llamar, basta» =', ['Just calling is enough.', 'With a call, stop.'], 0), mc('«salvo que» =', ['unless / except if', 'saved that'], 0), mc('Gerund as condition: «Saliendo ahora, llegamos» =', ['If we leave now, we’ll arrive.', 'Leaving now, we arrived.'], 0)]
    })
  ]);
